SELECT analytics_budget_facts.cost_center, AVG(analytics_budget_facts.budget_variance_pct) AS budget_variance_pct FROM analytics_budget_facts WHERE analytics_budget_facts.year = 2023 AND analytics_budget_facts.month = 7 AND analytics_budget_facts.department = 'department_02' AND analytics_budget_facts.expense_category = 'expense_04' GROUP BY analytics_budget_facts.cost_center ORDER BY budget_variance_pct DESC, analytics_budget_facts.cost_center ASC LIMIT 15
